//  \u0412\u0430\u0440\u0438\u0430\u043D\u0442 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F \u043D\u0430 \u0432\u043A\u043B\u0430\u0434\u043A\u0435 \xAB\u042F \u0443\u0447\u0443\xBB. \u041E\u0431\u0443\u0447\u0435\u043D\u043D\u044B\u0435 \u0432\u0435\u0441\u0430 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0442 \u043A \u043B\u044E\u0431\u043E\u043C\u0443.

import { sigmoid } from '../engine/utils.ts';

// \u041F\u0440\u044F\u043C\u043E\u0439 \u043F\u0440\u043E\u0445\u043E\u0434: \u0441\u043B\u043E\u0439 \u0437\u0430 \u0441\u043B\u043E\u0435\u043C \u0441\u0447\u0438\u0442\u0430\u0435\u043C \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u043D\u0435\u0439\u0440\u043E\u043D\u0430 \u0441\u0443\u043C\u043C\u0443 \xAB\u0432\u0445\u043E\u0434 \xD7 \u0432\u0435\u0441\xBB
// \u0438 \u043E\u0442\u0434\u0430\u0451\u043C \u0435\u0451 \u0444\u0443\u043D\u043A\u0446\u0438\u0438 activate(sum, bias, isOutput) \u2014 \u043E\u043D\u0430 \u0440\u0435\u0448\u0430\u0435\u0442, \u0447\u0442\u043E \u043D\u0435\u0439\u0440\u043E\u043D \xAB\u0441\u043A\u0430\u0436\u0435\u0442\xBB \u0434\u0430\u043B\u044C\u0448\u0435.
// isOutput = true \u0434\u043B\u044F \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u0441\u043B\u043E\u044F (\u0433\u0430\u0437, \u0442\u043E\u0440\u043C\u043E\u0437, \u0432\u043B\u0435\u0432\u043E, \u0432\u043F\u0440\u0430\u0432\u043E \u0438 \u0437\u0430\u043C\u0435\u0442\u043A\u0438 m1\u2026m3).
export function feedForward(inputs, brain, activate) {
  let values = inputs;
  const trace = [inputs];
  brain.layers.forEach((layer, k) => {
    const isOutput = k === brain.layers.length - 1;
    const next = [];
    for (let j = 0; j < layer.biases.length; j++) {
      let sum = 0;
      for (let i = 0; i < values.length; i++) {
        sum += values[i] * layer.weights[i][j];
      }
      next.push(activate(sum, layer.biases[j], isOutput));
    }
    values = next;
    trace.push(values);
  });
  feedForward.lastTrace = trace;
  return values;
}
// \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043F\u0440\u043E\u0445\u043E\u0434 \u043F\u043E \u0432\u0441\u0435\u043C \u0441\u043B\u043E\u044F\u043C \u2014 \u043F\u043E \u043D\u0435\u043C\u0443 \xAB\u042F \u0443\u0447\u0443\xBB \u043F\u043E\u0434\u0441\u0432\u0435\u0447\u0438\u0432\u0430\u0435\u0442 \u043D\u0435\u0439\u0440\u043E\u043D\u044B \u043D\u0430 \u0441\u0445\u0435\u043C\u0435
feedForward.lastTrace = null;

